def find_relevant_faqs(user_query, faqs, threshold=1):
    """
    Simple keyword-based search for relevant FAQs.
    Improve this with more sophisticated techniques (TF-IDF, embeddings) later.
    """
    user_query_lower = user_query.lower()
    relevant = []
    for faq in faqs:
        match_count = 0
        for keyword in faq.get("keywords", []):
            if keyword in user_query_lower:
                match_count += 1
        # Also check if keywords from the question itself match
        question_words = set(faq["question"].lower().split())
        query_words = set(user_query_lower.split())
        if question_words.intersection(query_words):
             match_count += len(question_words.intersection(query_words))

        if match_count >= threshold:
            relevant.append(faq)
    # Sort by match count descending if needed, or just return findings
    # Limit the number of returned FAQs to avoid overwhelming the context window
    return relevant[:3] # Return top 3 matches